/**
 * @summary List a mission's append-only journal events (paginated, user-scoped)
 */
export const getListProfitMissionEventsUrl = (
  id: number,
  params?: ListProfitMissionEventsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/profit-missions/${id}/events?${stringifiedParams}`
    : `/api/profit-missions/${id}/events`;
};

export const listProfitMissionEvents = async (
  id: number,
  params?: ListProfitMissionEventsParams,
  options?: RequestInit,
): Promise<MissionEvent[]> => {
  return customFetch<MissionEvent[]>(
    getListProfitMissionEventsUrl(id, params),
    {
      ...options,
      method: "GET",
    },
  );
};

