/**
 * @summary Fetch the Mission Risk Certificate content for a mission (Phase 9): honest, banned-vocabulary-clean summary plus the REQUIRED confirmation phrase. Read only. User/mission scoped.

 */
export const getGetMissionCertificateUrl = (
  id: number,
  params?: GetMissionCertificateParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/profit-missions/${id}/certificate?${stringifiedParams}`
    : `/api/profit-missions/${id}/certificate`;
};

export const getMissionCertificate = async (
  id: number,
  params?: GetMissionCertificateParams,
  options?: RequestInit,
): Promise<MissionCertificateContent> => {
  return customFetch<MissionCertificateContent>(
    getGetMissionCertificateUrl(id, params),
    {
      ...options,
      method: "GET",
    },
  );
};

export const getGetMissionCertificateQueryKey = (
  id: number,
  params?: GetMissionCertificateParams,
) => {
  return [
    `/api/profit-missions/${id}/certificate`,
    ...(params ? [params] : []),
  ] as const;
};

