/**
 * @summary Full management snapshot for an open trade
 */
export const getGetTradeSnapshotUrl = (id: number) => {
  return `/api/trade-management/${id}/snapshot`;
};

export const getTradeSnapshot = async (
  id: number,
  options?: RequestInit,
): Promise<TradeSnapshot> => {
  return customFetch<TradeSnapshot>(getGetTradeSnapshotUrl(id), {
    ...options,
    method: "GET",
  });
};

export const getGetTradeSnapshotQueryKey = (id: number) => {
  return [`/api/trade-management/${id}/snapshot`] as const;
};

export const getGetTradeSnapshotQueryOptions = <
  TData = Awaited<ReturnType<typeof getTradeSnapshot>>,
  TError = ErrorType<unknown>,
>(
  id: number,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getTradeSnapshot>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetTradeSnapshotQueryKey(id);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof getTradeSnapshot>>
  > = ({ signal }) => getTradeSnapshot(id, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!id,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getTradeSnapshot>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetTradeSnapshotQueryResult = NonNullable<
  Awaited<ReturnType<typeof getTradeSnapshot>>
>;
export type GetTradeSnapshotQueryError = ErrorType<unknown>;

