/**
 * @summary Upcoming economic events
 */
export const getGetEconomicCalendarUrl = (
  params?: GetEconomicCalendarParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/news/calendar?${stringifiedParams}`
    : `/api/news/calendar`;
};

export const getEconomicCalendar = async (
  params?: GetEconomicCalendarParams,
  options?: RequestInit,
): Promise<EconomicEvent[]> => {
  return customFetch<EconomicEvent[]>(getGetEconomicCalendarUrl(params), {
    ...options,
    method: "GET",
  });
};

