/**
 * @summary List all symbols in the registry
 */
export const getGetBrainSymbolsUrl = (params?: GetBrainSymbolsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/brain/symbols?${stringifiedParams}`
    : `/api/brain/symbols`;
};

export const getBrainSymbols = async (
  params?: GetBrainSymbolsParams,
  options?: RequestInit,
): Promise<SymbolRegistryItem[]> => {
  return customFetch<SymbolRegistryItem[]>(getGetBrainSymbolsUrl(params), {
    ...options,
    method: "GET",
  });
};

