/**
 * @summary Append-only event timeline for a live position
 */
export const getGetPositionEventsUrl = (
  id: number,
  params?: GetPositionEventsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/positions/${id}/events?${stringifiedParams}`
    : `/api/positions/${id}/events`;
};

export const getPositionEvents = async (
  id: number,
  params?: GetPositionEventsParams,
  options?: RequestInit,
): Promise<PositionEventList> => {
  return customFetch<PositionEventList>(getGetPositionEventsUrl(id, params), {
    ...options,
    method: "GET",
  });
};

