/**
 * @summary Most recent multi-timeframe report for a symbol
 */
export const getGetLatestMultiTimeframeReportUrl = (
  params: GetLatestMultiTimeframeReportParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/multi-timeframe/latest?${stringifiedParams}`
    : `/api/multi-timeframe/latest`;
};

