/**
 * @summary Profit-waterfall runs incl. ARX internal share (ADMIN/OWNER)
 */
export const getGetAdminFundBookWaterfallUrl = (
  params?: GetAdminFundBookWaterfallParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/fundbook/waterfall?${stringifiedParams}`
    : `/api/admin/fundbook/waterfall`;
};

