/**
 * @summary Trade-to-pool allocations (UNASSIGNED flagged), ADMIN/OWNER
 */
export const getGetAdminFundBookTradeAllocationsUrl = (
  params?: GetAdminFundBookTradeAllocationsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/fundbook/trade-allocations?${stringifiedParams}`
    : `/api/admin/fundbook/trade-allocations`;
};

