/**
 * @summary Caller's own capital movement requests
 */
export const getListMeCapitalRequestsUrl = (
  params?: ListMeCapitalRequestsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/me/capital/requests?${stringifiedParams}`
    : `/api/me/capital/requests`;
};

export const listMeCapitalRequests = async (
  params?: ListMeCapitalRequestsParams,
  options?: RequestInit,
): Promise<CapitalRequestsResp> => {
  return customFetch<CapitalRequestsResp>(getListMeCapitalRequestsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListMeCapitalRequestsQueryKey = (
  params?: ListMeCapitalRequestsParams,
) => {
  return [`/api/me/capital/requests`, ...(params ? [params] : [])] as const;
};

export const getListMeCapitalRequestsQueryOptions = <
  TData = Awaited<ReturnType<typeof listMeCapitalRequests>>,
  TError = ErrorType<unknown>,
>(
  params?: ListMeCapitalRequestsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listMeCapitalRequests>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getListMeCapitalRequestsQueryKey(params);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof listMeCapitalRequests>>
  > = ({ signal }) =>
    listMeCapitalRequests(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof listMeCapitalRequests>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

