/**
 * @summary List discrepancy records (ADMIN/OWNER)
 */
export const getListAdminFundBookDiscrepanciesUrl = (
  params?: ListAdminFundBookDiscrepanciesParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/fundbook/discrepancies?${stringifiedParams}`
    : `/api/admin/fundbook/discrepancies`;
};

