/**
 * @summary Remove a published statement / document for an investor (admin only)
 */
export const getDeleteAdminInvestorStatementUrl = (
  id: number,
  statementId: number,
  params?: DeleteAdminInvestorStatementParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/investors/${id}/statements/${statementId}?${stringifiedParams}`
    : `/api/admin/investors/${id}/statements/${statementId}`;
};

