/**
 * Returns a MarketTimingRead: heat score, tradeability, edge, danger, trap probability, room-to-move, buy/sell pressure, timing grade, entry permission, best action, session/kill-zone, news overlay, and broad-flow cross-asset context. All scores are advisory only and never gate live or demo execution.

 * @summary Get timing brain read for a single symbol
 */
export const getGetTimingBrainUrl = (
  symbol: string,
  params?: GetTimingBrainParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/me/timing-brain/${symbol}?${stringifiedParams}`
    : `/api/me/timing-brain/${symbol}`;
};

export const getTimingBrain = async (
  symbol: string,
  params?: GetTimingBrainParams,
  options?: RequestInit,
): Promise<MarketTimingRead> => {
  return customFetch<MarketTimingRead>(getGetTimingBrainUrl(symbol, params), {
    ...options,
    method: "GET",
  });
};

export const getGetTimingBrainQueryKey = (
  symbol: string,
  params?: GetTimingBrainParams,
) => {
  return [
    `/api/me/timing-brain/${symbol}`,
    ...(params ? [params] : []),
  ] as const;
};

export const getGetTimingBrainQueryOptions = <
  TData = Awaited<ReturnType<typeof getTimingBrain>>,
  TError = ErrorType<GetTimingBrain400 | GetTimingBrain401>,
>(
  symbol: string,
  params?: GetTimingBrainParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getTimingBrain>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getGetTimingBrainQueryKey(symbol, params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getTimingBrain>>> = ({
    signal,
  }) => getTimingBrain(symbol, params, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!symbol,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getTimingBrain>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

