/**
 * @summary Combined cockpit + platform audit timeline (admin/owner only).
 */
export const getGetAdminCockpitAuditLogUrl = (
  params?: GetAdminCockpitAuditLogParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/admin/cockpit/audit-log?${stringifiedParams}`
    : `/api/admin/cockpit/audit-log`;
};

